import { readFileSync, writeFileSync, mkdirSync } from "node:fs";

const deployment = JSON.parse(
  readFileSync(new URL("../deployments/moderato.json", import.meta.url), "utf8")
);
const artifact = JSON.parse(
  readFileSync(
    new URL("../artifacts/src/PolicyVault.sol/PolicyVault.json", import.meta.url),
    "utf8"
  )
);

const outDir = new URL("../../src/lib/", import.meta.url);
mkdirSync(outDir, { recursive: true });

const header =
  "// Generated by contracts/scripts/export-abi.mjs. Do not edit by hand.\n";

writeFileSync(
  new URL("vaultAbi.js", outDir),
  header + "export const VAULT_ABI = " + JSON.stringify(artifact.abi, null, 2) + ";\n"
);

writeFileSync(
  new URL("vaultConfig.js", outDir),
  header +
    "export const VAULT_ADDRESS = " + JSON.stringify(deployment.address) + ";\n" +
    "export const VAULT_TOKEN = " + JSON.stringify(deployment.token) + ";\n" +
    "export const VAULT_CHAIN_ID = " + deployment.chainId + ";\n" +
    "export const VAULT_DEPLOY_TX = " + JSON.stringify(deployment.deployTx) + ";\n"
);

console.log("Wrote src/lib/vaultAbi.js and src/lib/vaultConfig.js");
console.log("Vault:", deployment.address);
